def execute(arguments):
    """
    CSV文件处理

    参数:
        arguments (dict): 包含以下字段
            - operation (str): 操作类型
                - "read": 读取CSV文件
                - "write": 写入CSV文件
                - "filter": 过滤数据
                - "select": 选择列
            - file_path (str): CSV文件路径，必填
            - data (list): 要写入的数据，write操作必填，格式: [{"col1": "val1", ...}, ...]
            - columns (list): 要选择的列名列表，select操作必填
            - filter_column (str): 过滤的列名，filter操作必填
            - filter_value (str): 过滤的值，filter操作必填
            - delimiter (str): 分隔符，默认 ","
            - encoding (str): 文件编码，默认 "utf-8"
            - has_header (bool): 是否有表头，默认 True

    返回:
        dict: 包含处理结果的字典
            - success (bool): 是否成功
            - data (list): 读取/处理后的数据
            - rows (int): 行数
            - columns (list): 列名列表
            - error (str): 错误信息（失败时）
    """
    import os

    operation = arguments.get("operation", "read")
    file_path = arguments.get("file_path", "")
    data = arguments.get("data", [])
    columns = arguments.get("columns", [])
    filter_column = arguments.get("filter_column", "")
    filter_value = arguments.get("filter_value", "")
    delimiter = arguments.get("delimiter", ",")
    encoding = arguments.get("encoding", "utf-8")
    has_header = arguments.get("has_header", True)

    if not file_path:
        return {"success": False, "error": "请提供文件路径"}

    try:
        if operation == "read":
            if not os.path.exists(file_path):
                return {"success": False, "error": f"文件不存在: {file_path}"}

            with open(file_path, "r", encoding=encoding) as f:
                lines = f.read().strip().split("\n")

            if not lines:
                return {"success": True, "data": [], "rows": 0, "columns": []}

            if has_header:
                headers = lines[0].split(delimiter)
                rows = []
                for line in lines[1:]:
                    values = line.split(delimiter)
                    row = {headers[i]: values[i] if i < len(values) else "" for i in range(len(headers))}
                    rows.append(row)
                return {"success": True, "data": rows, "rows": len(rows), "columns": headers}
            else:
                rows = [line.split(delimiter) for line in lines]
                return {"success": True, "data": rows, "rows": len(rows), "columns": []}

        elif operation == "write":
            if not data:
                return {"success": False, "error": "请提供要写入的数据"}

            lines = []
            if has_header and isinstance(data[0], dict):
                headers = list(data[0].keys())
                lines.append(delimiter.join(headers))
                for row in data:
                    lines.append(delimiter.join(str(row.get(h, "")) for h in headers))
            else:
                for row in data:
                    if isinstance(row, dict):
                        lines.append(delimiter.join(str(v) for v in row.values()))
                    else:
                        lines.append(delimiter.join(str(v) for v in row))

            with open(file_path, "w", encoding=encoding) as f:
                f.write("\n".join(lines))

            return {"success": True, "rows": len(data), "file": file_path}

        elif operation == "filter":
            if not os.path.exists(file_path):
                return {"success": False, "error": f"文件不存在: {file_path}"}

            with open(file_path, "r", encoding=encoding) as f:
                lines = f.read().strip().split("\n")

            if not lines:
                return {"success": True, "data": [], "rows": 0}

            headers = lines[0].split(delimiter)
            if filter_column not in headers:
                return {"success": False, "error": f"列不存在: {filter_column}"}

            col_idx = headers.index(filter_column)
            filtered = []
            for line in lines[1:]:
                values = line.split(delimiter)
                if col_idx < len(values) and values[col_idx] == filter_value:
                    row = {headers[i]: values[i] if i < len(values) else "" for i in range(len(headers))}
                    filtered.append(row)

            return {"success": True, "data": filtered, "rows": len(filtered), "columns": headers}

        elif operation == "select":
            if not os.path.exists(file_path):
                return {"success": False, "error": f"文件不存在: {file_path}"}

            if not columns:
                return {"success": False, "error": "请提供要选择的列"}

            with open(file_path, "r", encoding=encoding) as f:
                lines = f.read().strip().split("\n")

            if not lines:
                return {"success": True, "data": [], "rows": 0}

            headers = lines[0].split(delimiter)
            selected_data = []
            for line in lines[1:]:
                values = line.split(delimiter)
                row = {headers[i]: values[i] if i < len(values) else "" for i in range(len(headers))}
                selected_row = {col: row.get(col, "") for col in columns}
                selected_data.append(selected_row)

            return {"success": True, "data": selected_data, "rows": len(selected_data), "columns": columns}

        else:
            return {"success": False, "error": f"未知的操作: {operation}"}
    except Exception as e:
        return {"success": False, "error": f"处理失败: {str(e)}"}
